const SENT_DATA = [{"id": 0, "chunks": ["我", "是", "学生。"], "zh": "我是学生。", "pinyin": "wǒ shì xué shēng.", "vi": "Tôi là học sinh.", "grammar": "Cấu trúc S + 是 + danh từ: khẳng định \"là\".", "level": "HSK1"}, {"id": 1, "chunks": ["他", "不是", "老师。"], "zh": "他不是老师。", "pinyin": "tā bú shì lǎo shī.", "vi": "Anh ấy không phải là giáo viên.", "grammar": "Phủ định của 是 là 不是 (không dùng 不 đứng riêng).", "level": "HSK1"}, {"id": 2, "chunks": ["你", "叫", "什么", "名字？"], "zh": "你叫什么名字？", "pinyin": "nǐ jiào shén me míng zì?", "vi": "Bạn tên là gì?", "grammar": "Câu hỏi dùng đại từ nghi vấn 什么 (gì/cái gì).", "level": "HSK1"}, {"id": 3, "chunks": ["我", "很", "高兴。"], "zh": "我很高兴。", "pinyin": "wǒ hěn gāo xìng.", "vi": "Tôi rất vui.", "grammar": "S + 很 + tính từ: câu vị ngữ tính từ (很 ở đây không nhất thiết dịch \"rất\").", "level": "HSK1"}, {"id": 4, "chunks": ["今天", "天气", "很", "好。"], "zh": "今天天气很好。", "pinyin": "jīn tiān tiān qì hěn hǎo.", "vi": "Hôm nay thời tiết rất đẹp.", "grammar": "Trạng ngữ thời gian đứng đầu câu, sau đó là vị ngữ tính từ.", "level": "HSK1"}, {"id": 5, "chunks": ["我", "每天", "六点", "起床。"], "zh": "我每天六点起床。", "pinyin": "wǒ měi tiān liù diǎn qǐ chuáng.", "vi": "Mỗi ngày tôi dậy lúc 6 giờ.", "grammar": "Trạng ngữ tần suất và thời gian đứng trước động từ chính.", "level": "HSK1"}, {"id": 6, "chunks": ["他", "在", "学校", "学习。"], "zh": "他在学校学习。", "pinyin": "tā zài xué xiào xué xí.", "vi": "Anh ấy học ở trường.", "grammar": "在 + địa điểm + động từ: giới từ chỉ nơi diễn ra hành động.", "level": "HSK1"}, {"id": 7, "chunks": ["我", "喜欢", "吃", "中国菜。"], "zh": "我喜欢吃中国菜。", "pinyin": "wǒ xǐ huān chī zhōng guó cài.", "vi": "Tôi thích ăn món Trung Quốc.", "grammar": "Động từ 喜欢 + cụm động từ làm tân ngữ.", "level": "HSK1"}, {"id": 8, "chunks": ["你", "有没有", "时间？"], "zh": "你有没有时间？", "pinyin": "nǐ yǒu méi yǒu shí jiān?", "vi": "Bạn có thời gian không?", "grammar": "Câu hỏi chính phản: 有没有 (có...không có).", "level": "HSK1"}, {"id": 9, "chunks": ["我", "没有", "钱。"], "zh": "我没有钱。", "pinyin": "wǒ méi yǒu qián.", "vi": "Tôi không có tiền.", "grammar": "Phủ định của 有 luôn là 没有, không dùng 不有.", "level": "HSK1"}, {"id": 10, "chunks": ["这", "是", "我的", "书。"], "zh": "这是我的书。", "pinyin": "zhè shì wǒ de shū.", "vi": "Đây là sách của tôi.", "grammar": "的 biểu thị sở hữu; 这 là chỉ thị từ \"đây/cái này\".", "level": "HSK1"}, {"id": 11, "chunks": ["那个", "人", "是", "谁？"], "zh": "那个人是谁？", "pinyin": "nà ge rén shì shuí?", "vi": "Người kia là ai?", "grammar": "那个: chỉ thị từ + lượng từ 个 trước danh từ chỉ người.", "level": "HSK1"}, {"id": 12, "chunks": ["我们", "一起", "去", "公园", "吧。"], "zh": "我们一起去公园吧。", "pinyin": "wǒ men yì qǐ qù gōng yuán ba.", "vi": "Chúng ta cùng đi công viên nhé.", "grammar": "吧 cuối câu biểu thị đề nghị, rủ rê.", "level": "HSK1"}, {"id": 13, "chunks": ["你", "会", "说", "汉语", "吗？"], "zh": "你会说汉语吗？", "pinyin": "nǐ huì shuō hàn yǔ ma?", "vi": "Bạn biết nói tiếng Hán không?", "grammar": "会 chỉ năng lực có được qua học tập; 吗 tạo câu hỏi có/không.", "level": "HSK1"}, {"id": 14, "chunks": ["我", "想", "喝", "咖啡。"], "zh": "我想喝咖啡。", "pinyin": "wǒ xiǎng hē kā fēi.", "vi": "Tôi muốn uống cà phê.", "grammar": "想 + động từ: diễn tả mong muốn làm gì.", "level": "HSK1"}, {"id": 15, "chunks": ["他", "正在", "看", "电视", "呢。"], "zh": "他正在看电视呢。", "pinyin": "tā zhèng zài kàn diàn shì ne.", "vi": "Anh ấy đang xem tivi.", "grammar": "正在...呢: diễn tả hành động đang xảy ra.", "level": "HSK2"}, {"id": 16, "chunks": ["我", "昨天", "去", "商店", "了。"], "zh": "我昨天去商店了。", "pinyin": "wǒ zuó tiān qù shāng diàn le.", "vi": "Hôm qua tôi đã đi cửa hàng.", "grammar": "了 sau động từ/cuối câu chỉ hành động đã hoàn thành.", "level": "HSK1"}, {"id": 17, "chunks": ["你", "吃饭", "了", "吗？"], "zh": "你吃饭了吗？", "pinyin": "nǐ chī fàn le ma?", "vi": "Bạn ăn cơm chưa?", "grammar": "了...吗: hỏi việc đã hoàn thành hay chưa.", "level": "HSK1"}, {"id": 18, "chunks": ["我", "还没", "吃", "早饭。"], "zh": "我还没吃早饭。", "pinyin": "wǒ hái méi chī zǎo fàn.", "vi": "Tôi chưa ăn sáng.", "grammar": "还没 + động từ: phủ định \"chưa làm gì\".", "level": "HSK2"}, {"id": 19, "chunks": ["他", "比", "我", "高。"], "zh": "他比我高。", "pinyin": "tā bǐ wǒ gāo.", "vi": "Anh ấy cao hơn tôi.", "grammar": "Cấu trúc so sánh hơn: A + 比 + B + tính từ.", "level": "HSK2"}, {"id": 20, "chunks": ["这个", "没有", "那个", "贵。"], "zh": "这个没有那个贵。", "pinyin": "zhè ge méi yǒu nà ge guì.", "vi": "Cái này không đắt bằng cái kia.", "grammar": "So sánh không bằng: A + 没有 + B + tính từ.", "level": "HSK2"}, {"id": 21, "chunks": ["我", "觉得", "汉语", "很", "有意思。"], "zh": "我觉得汉语很有意思。", "pinyin": "wǒ jué de hàn yǔ hěn yǒu yì si.", "vi": "Tôi thấy tiếng Hán rất thú vị.", "grammar": "觉得 + mệnh đề: diễn tả quan điểm, cảm nhận.", "level": "HSK2"}, {"id": 22, "chunks": ["请", "把", "门", "关上。"], "zh": "请把门关上。", "pinyin": "qǐng bǎ mén guān shàng.", "vi": "Làm ơn đóng cửa lại.", "grammar": "Câu chữ 把: 把 + tân ngữ + động từ + bổ ngữ, nhấn mạnh xử lý đối tượng.", "level": "HSK3"}, {"id": 23, "chunks": ["我", "被", "老师", "批评", "了。"], "zh": "我被老师批评了。", "pinyin": "wǒ bèi lǎo shī pī píng le.", "vi": "Tôi bị giáo viên phê bình rồi.", "grammar": "Câu bị động: chủ ngữ + 被 + tác nhân + động từ.", "level": "HSK3"}, {"id": 24, "chunks": ["因为", "下雨，", "所以", "我", "没", "去。"], "zh": "因为下雨，所以我没去。", "pinyin": "yīn wèi xià yǔ, suǒ yǐ wǒ méi qù.", "vi": "Vì trời mưa nên tôi không đi.", "grammar": "Cặp liên từ nhân quả 因为...所以.", "level": "HSK2"}, {"id": 25, "chunks": ["虽然", "很", "累，", "但是", "我", "很", "高兴。"], "zh": "虽然很累，但是我很高兴。", "pinyin": "suī rán hěn lèi, dàn shì wǒ hěn gāo xìng.", "vi": "Tuy mệt nhưng tôi rất vui.", "grammar": "Cặp liên từ nhượng bộ 虽然...但是.", "level": "HSK3"}, {"id": 26, "chunks": ["如果", "明天", "下雨，", "我们", "就", "不去", "了。"], "zh": "如果明天下雨，我们就不去了。", "pinyin": "rú guǒ míng tiān xià yǔ, wǒ men jiù bù qù le.", "vi": "Nếu mai trời mưa thì chúng ta không đi nữa.", "grammar": "Cặp câu điều kiện 如果...就.", "level": "HSK3"}, {"id": 27, "chunks": ["你", "一定", "要", "小心。"], "zh": "你一定要小心。", "pinyin": "nǐ yí dìng yào xiǎo xīn.", "vi": "Bạn nhất định phải cẩn thận.", "grammar": "一定 (nhất định) + 要 (phải) đứng trước động từ.", "level": "HSK2"}, {"id": 28, "chunks": ["我", "一边", "走路", "一边", "打电话。"], "zh": "我一边走路一边打电话。", "pinyin": "wǒ yī biān zǒu lù yī biān dǎ diàn huà.", "vi": "Tôi vừa đi bộ vừa gọi điện thoại.", "grammar": "Cấu trúc đồng thời 一边...一边.", "level": "HSK3"}, {"id": 29, "chunks": ["你", "越来越", "漂亮", "了。"], "zh": "你越来越漂亮了。", "pinyin": "nǐ yuè lái yuè piào liàng le.", "vi": "Bạn ngày càng xinh đẹp hơn.", "grammar": "越来越 diễn tả mức độ tăng dần theo thời gian.", "level": "HSK3"}, {"id": 30, "chunks": ["除了", "我，", "大家", "都", "去", "了。"], "zh": "除了我，大家都去了。", "pinyin": "chú le wǒ, dà jiā dōu qù le.", "vi": "Ngoài tôi ra, mọi người đều đi rồi.", "grammar": "除了...都: loại trừ một trường hợp ngoại lệ.", "level": "HSK3"}, {"id": 31, "chunks": ["只有", "努力，", "才", "能", "成功。"], "zh": "只有努力，才能成功。", "pinyin": "zhǐ yǒu nǔ lì, cái néng chéng gōng.", "vi": "Chỉ có nỗ lực mới có thể thành công.", "grammar": "只有...才: điều kiện duy nhất.", "level": "HSK3"}, {"id": 32, "chunks": ["他", "不但", "聪明，", "而且", "很", "努力。"], "zh": "他不但聪明，而且很努力。", "pinyin": "tā bù dàn cōng míng, ér qiě hěn nǔ lì.", "vi": "Anh ấy không những thông minh mà còn rất chăm chỉ.", "grammar": "Cặp câu tăng tiến 不但...而且.", "level": "HSK3"}, {"id": 33, "chunks": ["我", "一", "回家", "就", "睡觉。"], "zh": "我一回家就睡觉。", "pinyin": "wǒ yī huí jiā jiù shuì jiào.", "vi": "Tôi vừa về nhà là ngủ luôn.", "grammar": "Cấu trúc 一...就: vừa...là liền...", "level": "HSK3"}, {"id": 34, "chunks": ["你", "从", "哪儿", "来？"], "zh": "你从哪儿来？", "pinyin": "nǐ cóng nǎ ér lái?", "vi": "Bạn từ đâu đến?", "grammar": "从 + nơi chốn + động từ: chỉ điểm xuất phát.", "level": "HSK1"}, {"id": 35, "chunks": ["我", "到", "北京", "去", "旅游。"], "zh": "我到北京去旅游。", "pinyin": "wǒ dào běi jīng qù lǚ yóu.", "vi": "Tôi đến Bắc Kinh du lịch.", "grammar": "到 + địa điểm + 去 + động từ: chỉ mục đích di chuyển.", "level": "HSK2"}, {"id": 36, "chunks": ["请问，", "洗手间", "在", "哪儿？"], "zh": "请问，洗手间在哪儿？", "pinyin": "qǐng wèn, xǐ shǒu jiān zài nǎ ér?", "vi": "Xin hỏi, nhà vệ sinh ở đâu?", "grammar": "请问 mở đầu một câu hỏi lịch sự.", "level": "HSK1"}, {"id": 37, "chunks": ["一直", "往前", "走，", "就", "到", "了。"], "zh": "一直往前走，就到了。", "pinyin": "yì zhí wǎng qián zǒu, jiù dào le.", "vi": "Cứ đi thẳng về phía trước là tới.", "grammar": "一直 (luôn/thẳng) bổ nghĩa cho động từ chỉ hướng.", "level": "HSK2"}, {"id": 38, "chunks": ["我", "给", "妈妈", "打电话。"], "zh": "我给妈妈打电话。", "pinyin": "wǒ gěi mā mā dǎ diàn huà.", "vi": "Tôi gọi điện thoại cho mẹ.", "grammar": "给 + đối tượng + động từ: giới từ chỉ người nhận.", "level": "HSK1"}, {"id": 39, "chunks": ["他", "送给", "我", "一本书。"], "zh": "他送给我一本书。", "pinyin": "tā sòng gěi wǒ yī běn shū.", "vi": "Anh ấy tặng tôi một quyển sách.", "grammar": "Động từ song tân ngữ: 送给 + người + vật.", "level": "HSK2"}, {"id": 40, "chunks": ["我的", "手机", "坏", "了。"], "zh": "我的手机坏了。", "pinyin": "wǒ de shǒu jī huài le.", "vi": "Điện thoại của tôi bị hỏng rồi.", "grammar": "了 cuối câu chỉ sự thay đổi trạng thái.", "level": "HSK2"}, {"id": 41, "chunks": ["天", "快", "黑", "了。"], "zh": "天快黑了。", "pinyin": "tiān kuài hēi le.", "vi": "Trời sắp tối rồi.", "grammar": "快...了: sự việc sắp xảy ra.", "level": "HSK2"}, {"id": 42, "chunks": ["我", "学过", "三年", "汉语。"], "zh": "我学过三年汉语。", "pinyin": "wǒ xué guò sān nián hàn yǔ.", "vi": "Tôi đã từng học tiếng Hán 3 năm.", "grammar": "过 sau động từ chỉ kinh nghiệm đã từng trải qua.", "level": "HSK2"}, {"id": 43, "chunks": ["你", "去过", "中国", "吗？"], "zh": "你去过中国吗？", "pinyin": "nǐ qù guò zhōng guó ma?", "vi": "Bạn đã từng đến Trung Quốc chưa?", "grammar": "V + 过 + 吗: hỏi về kinh nghiệm đã từng làm.", "level": "HSK2"}, {"id": 44, "chunks": ["我们", "应该", "尊重", "老人。"], "zh": "我们应该尊重老人。", "pinyin": "wǒ men yīng gāi zūn zhòng lǎo rén.", "vi": "Chúng ta nên tôn trọng người già.", "grammar": "应该 + động từ: nên/phải làm gì.", "level": "HSK2"}, {"id": 45, "chunks": ["你", "可以", "帮", "我", "一下", "吗？"], "zh": "你可以帮我一下吗？", "pinyin": "nǐ kě yǐ bāng wǒ yī xià ma?", "vi": "Bạn có thể giúp tôi một chút không?", "grammar": "可以 + động từ; 一下 làm nhẹ hoá hành động (làm chút).", "level": "HSK2"}, {"id": 46, "chunks": ["我", "正在", "找", "工作。"], "zh": "我正在找工作。", "pinyin": "wǒ zhèng zài zhǎo gōng zuò.", "vi": "Tôi đang tìm việc làm.", "grammar": "正在 + động từ: hành động đang diễn ra.", "level": "HSK2"}, {"id": 47, "chunks": ["这件", "衣服", "太", "贵", "了。"], "zh": "这件衣服太贵了。", "pinyin": "zhè jiàn yī fú tài guì le.", "vi": "Bộ quần áo này quá đắt.", "grammar": "太...了: quá mức, thường mang sắc thái than phiền.", "level": "HSK1"}, {"id": 48, "chunks": ["我", "快要", "迟到", "了。"], "zh": "我快要迟到了。", "pinyin": "wǒ kuài yào chí dào le.", "vi": "Tôi sắp trễ rồi.", "grammar": "快要...了: sự việc sắp xảy ra (giống 快...了).", "level": "HSK2"}, {"id": 49, "chunks": ["你", "别", "担心。"], "zh": "你别担心。", "pinyin": "nǐ bié dān xīn.", "vi": "Bạn đừng lo lắng.", "grammar": "别 + động từ: câu cầu khiến phủ định \"đừng\".", "level": "HSK2"}, {"id": 50, "chunks": ["祝", "你", "生日快乐！"], "zh": "祝你生日快乐！", "pinyin": "zhù nǐ shēng rì kuài lè!", "vi": "Chúc bạn sinh nhật vui vẻ!", "grammar": "祝 + đối tượng + lời chúc: mẫu câu chúc mừng.", "level": "HSK2"}, {"id": 51, "chunks": ["对不起，", "我", "来晚", "了。"], "zh": "对不起，我来晚了。", "pinyin": "duì bù qǐ, wǒ lái wǎn le.", "vi": "Xin lỗi, tôi đến muộn rồi.", "grammar": "来晚: bổ ngữ trạng thái \"muộn\" sau động từ 来.", "level": "HSK1"}, {"id": 52, "chunks": ["没关系，", "别", "客气。"], "zh": "没关系，别客气。", "pinyin": "méi guān xì, bié kè qì.", "vi": "Không sao, đừng khách sáo.", "grammar": "Cụm từ đáp lễ thường dùng trong giao tiếp hàng ngày.", "level": "HSK1"}, {"id": 53, "chunks": ["我", "想", "跟", "你", "商量", "一件事。"], "zh": "我想跟你商量一件事。", "pinyin": "wǒ xiǎng gēn nǐ shāng liáng yī jiàn shì.", "vi": "Tôi muốn bàn với bạn một việc.", "grammar": "跟 + đối tượng + động từ: giới từ chỉ người cùng làm việc.", "level": "HSK3"}, {"id": 54, "chunks": ["你", "说", "得", "太", "快", "了。"], "zh": "你说得太快了。", "pinyin": "nǐ shuō dé tài kuài le.", "vi": "Bạn nói nhanh quá.", "grammar": "Bổ ngữ trình độ với 得: động từ + 得 + tính từ.", "level": "HSK2"}, {"id": 55, "chunks": ["他", "跑", "得", "很", "快。"], "zh": "他跑得很快。", "pinyin": "tā pǎo dé hěn kuài.", "vi": "Anh ấy chạy rất nhanh.", "grammar": "Bổ ngữ trình độ 得 diễn tả mức độ của động tác.", "level": "HSK2"}, {"id": 56, "chunks": ["我", "听不懂", "你", "说", "的", "话。"], "zh": "我听不懂你说的话。", "pinyin": "wǒ tīng bù dǒng nǐ shuō de huà.", "vi": "Tôi không hiểu lời bạn nói.", "grammar": "听不懂: bổ ngữ khả năng phủ định (nghe không hiểu).", "level": "HSK3"}, {"id": 57, "chunks": ["你", "做完", "作业", "了", "吗？"], "zh": "你做完作业了吗？", "pinyin": "nǐ zuò wán zuò yè le ma?", "vi": "Bạn làm xong bài tập chưa?", "grammar": "完 là bổ ngữ kết quả sau động từ, chỉ sự hoàn tất.", "level": "HSK2"}, {"id": 58, "chunks": ["我们", "下个星期", "见面", "吧。"], "zh": "我们下个星期见面吧。", "pinyin": "wǒ men xià gè xīng qī jiàn miàn ba.", "vi": "Tuần sau chúng ta gặp mặt nhé.", "grammar": "Trạng ngữ thời gian tương lai + động từ + 吧 đề nghị.", "level": "HSK2"}, {"id": 59, "chunks": ["你好，", "很", "高兴", "认识", "你。"], "zh": "你好，很高兴认识你。", "pinyin": "nǐ hǎo, hěn gāo xìng rèn shí nǐ.", "vi": "Xin chào, rất vui được quen bạn.", "grammar": "Cụm câu chào hỏi làm quen thông dụng.", "level": "HSK1"}, {"id": 60, "chunks": ["我", "家", "有", "四口人。"], "zh": "我家有四口人。", "pinyin": "wǒ jiā yǒu sì kǒu rén.", "vi": "Nhà tôi có 4 người.", "grammar": "有 chỉ sự tồn tại/sở hữu; 口 là lượng từ đếm người trong nhà.", "level": "HSK1"}, {"id": 61, "chunks": ["现在", "几点", "了？"], "zh": "现在几点了？", "pinyin": "xiàn zài jǐ diǎn le?", "vi": "Bây giờ mấy giờ rồi?", "grammar": "几点: câu hỏi về giờ giấc.", "level": "HSK1"}, {"id": 62, "chunks": ["今天", "是", "星期几？"], "zh": "今天是星期几？", "pinyin": "jīn tiān shì xīng qī jǐ?", "vi": "Hôm nay là thứ mấy?", "grammar": "星期几: câu hỏi về ngày trong tuần.", "level": "HSK1"}];

